// Find the specific targets in each project
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.Name == "Api.csproj")
    {
        var targets = p.FindChildrenRecursive<Target>();
        foreach (var t in targets)
        {
            if (t.Name == "CoreCompile" || t.Name == "Build" || t.Name == "ResolveProjectReferences")
            {
                var errors = t.FindChildrenRecursive<Error>();
                var msgs = t.FindChildrenRecursive<Message>();
                if (errors.Count > 0 || msgs.Any(m => m.Text?.Contains("failed") == true || m.Text?.Contains("not build") == true))
                {
                    Console.WriteLine($"Api.csproj Target={t.Name}:");
                    foreach (var e in errors)
                        Console.WriteLine($"  Error: [{e.Code}] {e.Text}");
                    foreach (var m in msgs.Where(m => m.Text?.Contains("failed") == true || m.Text?.Contains("not build") == true))
                        Console.WriteLine($"  Msg: {m.Text}");
                }
            }
        }
    }
}

